# Tien handgeschreven premisses uit run Z39-F4-0203 (seed 390203), elk met de canoncodes waar ze uit volgen.
# assen: personen, plek, patroon, belang, geheim (diversiteit: minstens 3 assen verschillend); spanning: botsende belangen, onomkeerbare keuzes, relevante geheimen.
RUN='Z39-F4-0203';SEED=390203
P=[
('IDEE-Z39-1',"Ondrea de Telster wil dat het register ook de dorpen zonder papier telt, en het eerste dorp dat ze bezoekt is dat van Kesh van de Neven, waar de kinderen elkaars neven zijn. Nessa Weigeraar heeft daar mannen verstopt en wil dat vrouwen blijven kiezen. Kesh kan haar dorp redden door Nessa's schuilplaats te noemen, of het dorp opgeven door te zwijgen, en Ondrea schrijft op wat ze ook kiest.",
 'PER-ondrea;PER-kesh-lijn;PER-nessa-weerstand;GEB-r10-eerste-register;GEB-r10-neven-ramp',('PER-kesh-lijn','PER-nessa-weerstand'),('groenmuil','verraad of ondergang','dorp laten bestaan','verstopte mannen'),(3,1,2)),
('IDEE-Z39-2',"Gunnar Bootsman werd zelf ooit geroofd en vaart nu mee op Ylva's rooftochten naar de eilanden van Runa van de Mist. Een man die hij daar meesleepte herkent hem als iemand van een andere clan en wil ermee terug naar huis. Gunnar wil vooral nooit meer van eigenaar wisselen, dus geeft hij de jongen bij Ylva aan voordat die hem kan aangeven, en hij weet dat hij daarmee doet wat hem zelf is aangedaan.",
 'PER-f4-clan-rover-gunnar;PER-f4-ylva;PER-f4-eiland-moeder-runa;GEB-r10-mannenroof;REG-stille',('PER-f4-clan-rover-gunnar','PER-f4-ylva'),('zoutkust','verraad','niet nog eens verkocht worden','andere clan'),(2,1,1)),
('IDEE-Z39-3',"Zuster Tine Telster vervalste één blad in Ambergaard om Brecht te laten gaan. Aaltje Zonderman, die ooit zelf een man in haar schuur verborg, ziet dat het blad niet klopt. Tine dreigt dat oude geheim te noemen, maar Aaltje gaat toch naar Saelith. Na die reis heeft geen van beiden nog iemand in het dorp die voor haar wil liegen.",
 'PER-f4-registerzuster-tine;PER-f4-buurvrouw-aaltje;PER-f4-brecht;VALS-noodtoestand;GEB-r10-deelwet-weerstand',('PER-f4-registerzuster-tine','PER-f4-buurvrouw-aaltje'),('ambergaard','wederzijdse chantage','eigen schuld kwijt','verborgen man'),(2,1,2)),
('IDEE-Z39-4',"Isolde Edrunsdochter is negentien en weet dat Saske heeft gelogen over wie haar vader is. Om Saske voor te zijn klaagt ze Orvath de Moeras aan, die zijn beurten laat lopen voor een geroofde eilander. Saske slaat terug door Isoldes eigen blad open te leggen, en zo staat de dochter van de laatste koning ineens in het register waar ze zich voor verborg.",
 'PER-f4-dochter-edrun;PER-f4-saske;PER-orvath;PER-f4-edrun;GEB-r10-laatste-koning',('PER-f4-dochter-edrun','PER-orvath'),('zoutkust','verraad met tegenzet','afkomst geheim houden','vaderschap'),(3,2,2)),
('IDEE-Z39-5',"Hofmeesteres Gerdien weet welke jongens in het Hof verwant zijn, en ze houdt van een man die Ylva van de eilanden roofde. Hij heeft gezien hoe ze de lijsten schuift en wil met die kennis een boot naar huis kopen. Geeft ze hem de boot, dan gaat ook haar lijst mee naar wie hem op de eilanden wil lezen. Houdt ze hem vast, dan heeft ze de enige vreemde verraden die haar ooit om zichzelf koos.",
 'PER-f4-jongenshof-meester;GEB-r10-jongenshof;GEB-r10-mannenroof;PER-ithra-oud',('PER-f4-jongenshof-meester','PER-f4-ylva'),('saelith','chantage door een geliefde','het Hof veilig houden','verwante jongens'),(2,1,1)),
('IDEE-Z39-6',"Fenna Rekenaarster schrijft rustmaanden in het rooster die niemand verdiend heeft. Ze merkt dat Ruben Gedeelde, beurt na beurt, nooit een kind verwekt. Laat ze dat staan, dan beschermt ze een onvruchtbare man die liever bij één geliefde blijft; meldt ze het, dan valt haar eigen gesjoemel mee om. Ze kiest voor Ruben en betaalt met de eerste vraag die Moeder Iris over het rooster stelt.",
 'PER-f4-zuster-ondrea-leerling;PER-f4-gedeelde-man-ruben;PER-f4-orde-moeder-iris;GEB-r10-rotatie;GEB-r10-uitputting',('PER-f4-zuster-ondrea-leerling','PER-f4-gedeelde-man-ruben'),('ambergaard','medeplichtig zwijgen','het rooster eerlijk maken','onvruchtbaarheid'),(3,1,2)),
('IDEE-Z39-7',"Orvath de Moeras deelt met Runa van de Mist een bed en een geheim: de Oevrin hebben één op twee en geen Zegel. Runa wil haar eilanden buiten de rotatie houden en ziet in de slikgangen een schuilplaats voor mannen. Orvath weet dat de Orde zijn volk gaat leegroven zodra iemand die gangen ziet. Hun weigering en hun liefde kunnen niet allebei geheim blijven.",
 'PER-orvath;PER-f4-eiland-moeder-runa;GEB-r10-eilanden-weigering;UIT-VOLK-saelmor',('PER-orvath','PER-f4-eiland-moeder-runa'),('stille','geheim tussen geliefden','volk verbergen','Oevrin zonder Zegel'),(2,1,1)),
('IDEE-Z39-8',"Moeder Iris en Fenna zweren allebei trouw aan Gerdien, de vrouw die het Hof echt bestuurt. Iris schreef de eerste liturgie in het geheim en wil dat de Orde een kerk wordt; Fenna wil een eerlijk rooster. Wie van de twee Gerdien kiest, wordt opvolgster. De ander moet dan haar geheim zien te houden tegenover de vrouw die het al kent.",
 'PER-f4-orde-moeder-iris;PER-f4-zuster-ondrea-leerling;PER-f4-jongenshof-meester;GEB-r10-orde-naam;GEB-r10-dankpreek',('PER-f4-orde-moeder-iris','PER-f4-jongenshof-meester'),('saelith','rivaliteit om een derde','opvolging','eerste liturgie'),(2,1,2)),
('IDEE-Z39-9',"Lise Zonderkind wil geen kind, alleen een eigen leven, en vlucht met een Tharn-vrouw over de pas naar de dijken van Bula. In Hoogvrouwe kent niemand het register, maar de Zegel raakt ook de Tharn, en Bula heeft handen nodig, geen gasten. Lise moet kiezen: de dijk mee bouwen tot ze bij die mensen hoort, of terug naar een rooster dat haar weigering opschrijft.",
 'PER-f4-boerin-lise;PER-f4-tharn-bula;REG-hoogvrouwe;KAART-seizoenen;WET-wie-weigert',('PER-f4-boerin-lise','PER-f4-tharn-bula'),('hoogvrouwe','vlucht','eigen leven','Zegel raakt de Tharn'),(2,1,1)),
('IDEE-Z39-10',"Dries Pontbaas bewaart de ring van koning Edrun en zou die voor geen register afgeven. Hij heeft Saske eens aangegeven om een schuld af te lossen. Nu klaagt een buurman hem aan omdat hij zijn beurt laat lopen voor Aaltje. Saske biedt hem een uitweg: de ring tegen een schone lei. Neemt Dries die, dan is het laatste bewijs van de laatste koning in handen van de vrouw die hem liet vallen.",
 'PER-f4-veerman-dries;PER-f4-edrun;PER-f4-saske;PER-f4-buurvrouw-aaltje;ZAAD-VERHAAL-fase4-a',('PER-f4-veerman-dries','PER-f4-buurvrouw-aaltje'),('saelith','ruil onder dreiging','herberg en ring houden','Edruns ring'),(3,1,1)),
]
